validation.command:
@'
import assert from 'node:assert/strict';
import { existsSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { loadPackageFromDirectory, validatePackage } from '@jvm-expert/core';
import { NodeFileSystem } from '@jvm-expert/node';
import { ClaudeCodeAdapter } from '@jvm-expert/adapter-claude';
import { CodexAdapter } from '@jvm-expert/adapter-codex';
const directory = resolve('skills/object-layout-and-footprint');
const loaded = await loadPackageFromDirectory(new NodeFileSystem(), directory, { strict: true });
const report = validatePackage(loaded.pkg, {
  strict: true, directoryName: 'object-layout-and-footprint',
  adapters: [new ClaudeCodeAdapter(), new CodexAdapter()],
});
const issues = [...loaded.issues, ...report.issues];
assert.deepEqual(issues, []);
assert.equal(loaded.pkg.manifest.version, '1.4.5');
const declared = new Set([
  ...(loaded.pkg.manifest.dependencies ?? []).map(item => item.name),
  ...(loaded.pkg.manifest.suggests ?? []),
]);
const referrals = new Set();
let localMarkdownLinks = 0;
for (const file of loaded.pkg.files.filter(file => file.path.endsWith('.md'))) {
  const content = readFileSync(resolve(directory, file.path), 'utf8');
  for (const match of content.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)) {
    if (/^<?https?:/.test(match[1])) continue;
    const [target, anchor] = match[1].split('#');
    const absolute = resolve(directory, dirname(file.path), target);
    assert.ok(existsSync(absolute), file.path + ': ' + match[1]);
    if (anchor === 'one-incoming-intent-several-downstream-effects') {
      assert.ok(readFileSync(absolute, 'utf8').includes('## One incoming intent, several downstream effects'));
    }
    localMarkdownLinks++;
  }
  for (const match of content.matchAll(/`([a-z][a-z0-9]*-[a-z0-9-]+)`/g)) {
    const name = match[1];
    if (!existsSync(resolve('skills', name, 'SKILL.md'))) continue;
    assert.ok(declared.has(name), 'Undeclared referral: ' + name);
    referrals.add(name);
  }
}
console.log(JSON.stringify({
  status: 'PASS', name: loaded.pkg.manifest.name, version: loaded.pkg.manifest.version,
  files: loaded.pkg.files.length, issues: issues.length, localMarkdownLinks,
  declaredSkillReferrals: referrals.size, adapters: ['claude', 'codex'],
}));
'@ | node --input-type=module

technicalExecutions.command:
@'
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {writeFileSync} from 'node:fs';
const bin='C:/Users/robso/.jdks/temurin-25.0.3/bin/';
const jol='C:/Users/robso/.m2/repository/org/openjdk/jol/jol-core/0.17/jol-core-0.17.jar';
const env={...process.env};
for(const name of Object.keys(env)) if(['JAVA_TOOL_OPTIONS','JDK_JAVA_OPTIONS','_JAVA_OPTIONS'].includes(name.toUpperCase())) delete env[name];
const runs=[];
function run(name, executable, args) {
 const p=spawnSync(bin+executable,args,{cwd:process.cwd(),env,encoding:'utf8',timeout:20000,windowsHide:true});
 const record={name,executable:bin+executable,args,status:p.status,stdout:p.stdout,stderr:p.stderr,error:p.error?.message};
 runs.push(record);
 writeFileSync('probe-log.json',JSON.stringify(runs,null,2));
 if(p.error) throw p.error;
 assert.equal(p.status,0,name);
 return p;
}
run('compiler version','javac.exe',['-version']);
run('runtime version','java.exe',['-version']);
run('compile release 25','javac.exe',['--release','25','-cp',jol,'-d','classes','PrintableProbe.java']);
let passing=0;
for(const mode of ['classic','compact']) {
 const flags=['-Xms32m','-Xmx128m','-XX:+UseCompressedOops','-XX:+UseCompressedClassPointers','-XX:ObjectAlignmentInBytes=8',
  '-Djol.magicFieldOffset=true','-Djol.skipInstallAttach=true','-Djol.skipDynamicAttach=true','-Djol.skipHotspotSAAttach=true',
  mode==='classic'?'-XX:-UseCompactObjectHeaders':'-XX:+UseCompactObjectHeaders'];
 const source=run(mode+' source launch','java.exe',[...flags,'-cp',jol,'PrintableProbe.java','source']);
 assert.match(source.stdout,/PASS checks=10/); passing++;
 const compiled=run(mode+' compiled launch','java.exe',[...flags,'-cp','classes;'+jol,'PrintableProbe','compiled']);
 assert.match(compiled.stdout,/PASS checks=10/); passing++;
}
console.log(JSON.stringify({status:'PASS',configurations:passing,fixtureAssertions:40,compilerTarget:25,
 runtime:'Temurin 25.0.3+9 Windows x64',artifact:'probe-log.json',
 outputs:runs.filter(r=>r.name.includes('launch')).map(r=>({name:r.name,result:r.stdout.split(/\r?\n/).filter(line=>line.includes('size=')||line.includes('PASS')).join('\n')}))}));
